// Riceberg's corrected thesis is foundational AI ONLY, explicitly not application-layer
// platforms; Siana's is deep-tech / IP-led (healthtech, battery, biotech, medtech) at a
// US$1M floor. These pending pairs fail one or the other, so they must never be sent.
// Every row here is unsent - sent rows carry thread_id and are never deleted.
const T = [
  ['D01660','Riceberg Ventures'],['D02265','Riceberg Ventures'],['D03212','Riceberg Ventures'],
  ['D00268','Siana Capital'],['D00496','Siana Capital'],['D00528','Siana Capital'],
  ['D00578','Siana Capital'],['D01132','Siana Capital'],['D01621','Siana Capital'],
  ['D01637','Siana Capital'],['D02214','Siana Capital'],['D02296','Siana Capital'],
  ['D02367','Siana Capital'],['D02378','Siana Capital'],['D02460','Siana Capital'],
  ['D02699','Siana Capital'],['D02774','Siana Capital'],['D03070','Siana Capital'],
  ['D03071','Siana Capital'],['D03072','Siana Capital'],['D03073','Siana Capital']
];
function s(v){return String(v==null?'':v).trim();}
const rows=$input.all().map(i=>i.json);
if(rows.length<500){throw new Error('ABORT: PIPELINE returned only '+rows.length+' rows');}
if(T.length!==21){throw new Error('ABORT: expected 21 targets, have '+T.length);}
const out=[];
for(const t of T){
  const id=t[0], inv=t[1];
  const h=rows.filter(r=>s(r.deal_id)===id);
  if(h.length!==1){throw new Error('ABORT: expected 1 row for '+id+', found '+h.length);}
  if(s(h[0].investor)!==inv){throw new Error('ABORT: '+id+' belongs to '+s(h[0].investor)+', expected '+inv);}
  if(s(h[0].deal_shared).toLowerCase()==='yes'){throw new Error('ABORT: '+id+' already sent - refusing to delete');}
  if(s(h[0].investor_response)!==''){throw new Error('ABORT: '+id+' has an investor_response - refusing to delete');}
  if(!h[0].row_number){throw new Error('ABORT: no row_number for '+id);}
  out.push({json:{row_number:Number(h[0].row_number),deal_id:id,investor:s(h[0].investor),startup:s(h[0].startup)}});
}
if(out.length!==T.length){throw new Error('ABORT: resolved '+out.length+' of '+T.length);}
if(out.length>25){throw new Error('ABORT: guard - '+out.length+' deletions exceeds 25');}
out.sort((a,b)=>b.json.row_number-a.json.row_number);
for(let i=1;i<out.length;i++){if(out[i].json.row_number===out[i-1].json.row_number){throw new Error('ABORT: duplicate row_number');}}
return out;
